let specSearch='',specStatus='All',selfType='All';
function specPage(){const rows=specificationAudit.requirements.filter(r=>(specStatus==='All'||r.status===specStatus)&&`${r.section} ${r.requirement}`.toLowerCase().includes(specSearch.toLowerCase()));return heading('Specification and delivery audit','Source-linked requirements · Reviewed '+specificationAudit.reviewed)+`<section class="card prose"><h2>Scope and conflicts</h2><p><a class="button secondary" href="verified-gap-review.txt" download>Download verified feature review</a></p>${listHTML(specificationAudit.conflicts)}<h3>Remaining production dependencies</h3>${listHTML(specificationAudit.blockers)}<p>${academyLink('Download full audit','spec-audit.json')}</p><label>Find requirement<input id="spec-search" value="${esc(specSearch)}" type="search"></label><label>Status<select id="spec-status">${['All','RELATED PREVIEW','UNVERIFIED'].map(s=>`<option ${s===specStatus?'selected':''}>${s}</option>`).join('')}</select></label><p>${rows.length} requirements. Showing the first 100 matches; narrow the search for more. Inventory labels are automated triage, not feature-level acceptance results. Related preview means a keyword matches existing content or UI.</p>${rows.slice(0,100).map(r=>`<details><summary>${esc(r.id)} · ${r.status} · ${esc(r.requirement.slice(0,150))}</summary><p>${esc(r.requirement)}</p><p><b>Evidence:</b> ${esc(r.evidence)}</p><small>${esc(r.source)} · line ${r.line} · ${esc(r.section)}</small></details>`).join('')}</section>`;}
const selfTypes={28:'Professional Certificate',29:'Professional Certificate',30:'Specialization',31:'Specialization',32:'Short Course',33:'Specialization',34:'Short Course',35:'Guided Project',36:'Guided Project',37:'Specialization',38:'Specialization'};
function selfPacedHub(){const ps=programCatalog.filter(p=>p.id>=28&&p.id<=38&&(selfType==='All'||selfTypes[p.id]===selfType));return heading('Agentic AI courses and certificates','Build a path from a guided project to a professional certificate.')+`<section class="card prose"><p>Scholarion Academy · Non-credit professional learning. These are curriculum previews. Fees, subscriptions and live course access are not configured.</p><label>Product type<select id="self-type">${['All','Guided Project','Short Course','Specialization','Professional Certificate'].map(x=>`<option ${x===selfType?'selected':''}>${x}</option>`).join('')}</select></label><p>Start with <a href="#program/32">design patterns</a>, <a href="#program/37">machine learning foundations</a>, or <a href="#program/34">leadership</a>. Progress through #30/#31 to #28 and the live pathways. Transfer remains subject to curriculum approval.</p></section><div class="course-grid">${ps.map(p=>`<article class="card prose"><span class="tag">${selfTypes[p.id]}</span><h2>${esc(p.title)}</h2><p>${esc(p.summary)}</p><p>${esc(p.length)} · ${esc(p.coding)}</p>${btn('Program details','#program/'+p.id,true)} <button class="button secondary" data-spec-badge="${p.id}">Design program badge</button></article>`).join('')}</div>`;}
const beforeSpecIntegration=render;render=function(){const route=location.hash.slice(1);if(['spec-audit','self-paced'].includes(route)){document.getElementById('app').innerHTML=integratedShell(route,route==='spec-audit'?specPage():selfPacedHub(),model.role);decorateRole(model.role);bind();}else beforeSpecIntegration();const nav=document.querySelector('.sidebar nav');if(nav)nav.insertAdjacentHTML('beforeend',`<a class="nav-item" href="#self-paced">${icon('book')}Self-paced catalog</a><a class="nav-item" href="#spec-audit">${icon('file')}Specification audit</a>`);if(route==='catalog')document.querySelector('main')?.insertAdjacentHTML('afterbegin',`<p>${btn('Browse self-paced offerings','#self-paced',true)}</p>`);};
document.addEventListener('change',e=>{if(e.target.id==='spec-status'){specStatus=e.target.value;render();}if(e.target.id==='spec-search'){specSearch=e.target.value;render();}if(e.target.id==='self-type'){selfType=e.target.value;render();}});
document.addEventListener('click',e=>{const t=e.target.closest('[data-spec-badge]');if(!t)return;const p=findProgram(t.dataset.specBadge);badgeConfig={id:p.id,title:p.title,type:selfTypes[p.id]==='Guided Project'?'Completion Badge':selfTypes[p.id],style:'ribbon'};location.hash='badge-generator';});
render();



